fn certified(f:&Fixture)->CertifiedComponent{certified_component(&f.census,&f.canonical,&Certificates{values:&f.certs,trusted_sha256:&f.trusted,rule_receipts:&f.rules},R,&f.policy).unwrap()}
fn held_bank(f:&Fixture,side:&str,n:u64)->AdmissionBank{let mut b=admission_bank(f);let signed=if side=="NO"{-(n as i64)}else{n as i64};let r=receipt(format!("/tournaments/{}/portfolio/positions",f.census.cache.scope.tournament_slug),json!({"positions":[{"exchangeId":"101","marketId":"201","quantity":signed,"costBasis":n as f64*0.2,"lots":[{"lotId":"9101","quantity":n,"side":side,"entryPrice":0.2,"openedAt":AT}]}]}));let e=inventory::adoption(&r,b.bank.engine(),T,&f.census.cache.scope.tournament_slug,&f.census.cache.scope.exchanges,AT).unwrap();b.bank.accept("adoption",1,&e).unwrap();
 // Real native retirement of original never-submitted quotes, not a fabricated
 // flat order view. Keep the original timestamp and source causal ordering.
 for (i,q) in b.bank.engine().order_records().into_iter().filter(|q|q["retired"]==false).enumerate(){
 let e=json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","orderId":q["id"],"confirmedNetworkAttempts":0,"receiptHash":"e".repeat(64),"receivedAt":AT});
 b.bank.accept("fixture-retire",i as u64+1,&e).unwrap();
 }b}
fn counterexample()->Fixture{let mut f=fixture(2,true);f.policy.quantities=vec![5];f.policy.maximum_quantity=5;f.policy.buffer_per_share=0;f.books.get_mut("102").unwrap().no_asks=level(500000);f}
fn complete_real_session_package(f:&Fixture,b:&mut AdmissionBank)->String{let a=admit_fixture(f,b).unwrap().unwrap();let id=a.package_id().to_owned();let mut n=1u64;b.bank.accept("owned-package",n,a.reserve_event()).unwrap();let mut attempt=a.reserve_event().clone();attempt["type"]=json!("live_package_attempt");attempt["receivedAt"]=json!(daily_windows::iso(now()+3000).unwrap());attempt["processedAt"]=attempt["receivedAt"].clone();attempt["requestHash"]=json!("c".repeat(64));attempt["idempotencyKey"]=json!(a.basket().idempotency_key);attempt["bookHashes"]=b.bank.engine().live_package_books().iter().map(|raw|(raw["exchangeId"].as_str().unwrap().to_owned(),json!(format!("{:x}",Sha256::digest(serde_json::to_vec(raw).unwrap()))))).collect::<serde_json::Map<_,_>>().into();n+=1;b.bank.accept("owned-package",n,&attempt).unwrap();for q in b.bank.engine().order_records(){let at=daily_windows::iso(now()+3001).unwrap();let mut e=json!({"type":"actual_order_ack","source":"official_sig_api_v1","receiptHash":"d".repeat(64),"orderId":q["id"],"actualOrderId":format!("90{}",q["id"].as_u64().unwrap()),"exchangeId":q["exchangeId"],"marketId":q["marketId"],"side":q["side"],"action":q["action"],"quantity":q["quantity"],"price":q["price"],"receivedAt":at});n+=1;b.bank.accept("owned-package",n,&e).unwrap();e["type"]=json!("actual_fill");e["fillId"]=json!(format!("80{}",q["id"].as_u64().unwrap()));e["fee"]=json!("0.000000");e["executedAt"]=e["receivedAt"].clone();n+=1;b.bank.accept("owned-package",n,&e).unwrap();e["type"]=json!("actual_order_terminal");e["filledQuantity"]=q["quantity"].clone();e["fillsComplete"]=json!(true);e["status"]=json!("filled");n+=1;b.bank.accept("owned-package",n,&e).unwrap();}attempt["type"]=json!("live_package_complete");attempt["receivedAt"]=json!(daily_windows::iso(now()+3002).unwrap());attempt["processedAt"]=attempt["receivedAt"].clone();n+=1;b.bank.accept("owned-package",n,&attempt).unwrap();id}
