fn physical_fixture()->Fixture{
 let mut f=counterexample();f.policy.max_relationship_age_ms=180_000;f.certs[0].version=2;f.certs[0].expires_at_ms=now()+120_000;
 f.certs[0].canonical_relationship_sha256=relationship_semantics_sha256(&f.census.cache.relationships.as_ref().unwrap().data[0]).unwrap();
 for(i,r)in f.rules.iter_mut().enumerate(){r.endpoint=format!("/markets/{}/nodes?tournamentId={T}",201+i);r.data["contexts"]=json!([{"type":"tournament","tournament":{"id":T}}]);let c=&mut f.certs[0].contracts[i];c.rule_endpoint=r.endpoint.clone();c.rule_receipt_sha256=receipt_sha256(r).unwrap();c.rule_data_sha256=Some(rule_data_sha256(r).unwrap());}
 f.rules.push(f.canonical.clone());f.approve();f
}
struct A{f:Fixture,b:AdmissionBank,plan:package_portfolio::Plan,basket:wire::Basket,permit:Permit,spec:RequestSpec,facts:PackageSnapshotSet,at:u64}
impl A{
 fn buy()->Self{let f=physical_fixture();let b=held_bank(&f,"NO",5);let c=certified(&f);let plan=package_portfolio::acquire(&b.bank,&b.activation,&c,1000*UNIT,&f.policy,b.activation.entry_until_ms).unwrap().unwrap();Self::stage(f,b,plan)}
 fn sell()->Self{let mut f=physical_fixture();let mut b=admission_bank(&f);let id=complete_real_session_package(&f,&mut b);f.policy.now_ms=now()+61_000;
 for(index,ex)in ["101","102"].iter().enumerate(){let at=stamp(f.policy.now_ms);b.bank.accept("after-entry-book",index as u64+1,&json!({"type":"book","receivedAt":at,"book":{"tournamentId":T,"marketId":f.census.cache.scope.exchanges[*ex],"exchangeId":ex,"sequence":"2","requestStartedAt":at,"sourceAt":at,"receivedAt":at,"bids":[{"price":"0.350000","quantity":100}],"asks":[{"price":"0.400000","quantity":100}]}})).unwrap();}
 let c=certified(&f);let plan=package_portfolio::whole_unwind(&b.bank,&b.activation,&c,&id,&f.policy,b.activation.entry_until_ms).unwrap().unwrap();Self::stage(f,b,plan)}
 fn stage(f:Fixture,mut b:AdmissionBank,plan:package_portfolio::Plan)->Self{
 let scope=&f.census.cache.scope;let basket=wire::Basket{idempotency_key:format!("{}:{}",b.activation.run_id,plan.package_id()),tournament_id:T.into(),legs:plan.legs().iter().map(|l|wire::Leg{exchange_id:l.exchange_id.clone(),side:if l.side=="YES"{multi_leg::Side::Yes}else{multi_leg::Side::No},action:if l.action=="buy"{wire::Action::Buy}else{wire::Action::Sell},quantity:l.quantity as u32,limit_price:l.limit_price.clone()}).collect(),maximum_gross_buy_cost:plan.proof()["grossFunding"].as_str().unwrap().into(),minimum_gross_sell_proceeds:plan.proof()["minimumCashProceeds"].as_str().unwrap().into(),relationship_constraint:None};
 let permit=Permit{run_id:b.activation.run_id.clone(),intent_id:plan.package_id().into(),owner:"Codex".into(),expires_at_ms:plan.expires_at_ms(),maximum_quantity:100,maximum_cost:basket.maximum_gross_buy_cost.clone()};let spec=wire::request_spec(&basket,scope,&permit).unwrap();
 b.bank.accept("authority-portfolio",1,plan.reserve_event()).unwrap();let at=f.policy.now_ms+3000;let mut event=plan.reserve_event().clone();event["type"]=json!("live_package_attempt");event["receivedAt"]=json!(stamp(at));event["processedAt"]=event["receivedAt"].clone();event["requestHash"]=json!(sha(&spec));event["idempotencyKey"]=json!(basket.idempotency_key);event["bookHashes"]=b.bank.engine().live_package_books().iter().map(|r|(r["exchangeId"].as_str().unwrap().to_owned(),json!(sha(r)))).collect::<serde_json::Map<_,_>>().into();b.bank.accept("authority-portfolio",2,&event).unwrap();
 let mut components=BTreeMap::new();for(ex,market)in &scope.exchanges{let raw=b.bank.engine().live_package_books().into_iter().find(|r|r["exchangeId"]==*ex).unwrap();let levels=|key:&str|raw[key].as_array().unwrap().iter().map(|r|json!({"price":serde_json::from_str::<Value>(r["price"].as_str().unwrap()).unwrap(),"quantity":r["quantity"]})).collect::<Vec<_>>();
 let mut contract=f.rules.iter().find(|r|r.data["market_id"]==*market).unwrap().clone();contract.request_started_at=stamp(at);contract.received_at=stamp(at);
 let r=|endpoint:String,data:Value|Receipt{endpoint,status:200,request_started_at:stamp(at),received_at:stamp(at),data};
 components.insert(ex.clone(),ComponentSnapshots{market:r(format!("/markets/{}?tournamentId={T}",*market),json!({"id":*market,"status":"open","isComposite":false,"isMultiOutcome":false,"contexts":[{"type":"tournament","tournament":{"id":T},"status":"open"}]})),contract,book:r(format!("/markets/{}/orderbook?tournamentId={T}&depth=20",*market),json!({"contexts":[{"type":"tournament","tournament":{"id":T},"orderbook":{"exchanges":[{"exchangeId":*ex,"asOf":{"sequence":raw["sequence"].as_str().unwrap().parse::<u64>().unwrap(),"at":raw["sourceAt"]},"bids":levels("bids"),"asks":levels("asks")}]}}]}))});}
 let r=|endpoint:String,data:Value|Receipt{endpoint,status:200,request_started_at:stamp(at),received_at:stamp(at),data};let w=&b.bank.engine().wallet;let cash=1000*UNIT+w.cash-w.initial+b.bank.engine().opening_inventory_cost();
 let positions=scope.exchanges.iter().filter_map(|(ex,m)|{let n=w.quantity(ex,moloch_replay::Side::Yes) as i64-w.quantity(ex,moloch_replay::Side::No) as i64;(n!=0).then(||json!({"exchangeId":ex,"marketId":m,"quantity":n}))}).collect::<Vec<_>>();
 let facts=PackageSnapshotSet{account:r(format!("/tournaments/{}",scope.tournament_slug),json!({"id":T,"slug":scope.tournament_slug,"status":"active","endDate":stamp(now()+180000)})),cash_balance:r(format!("/account?tournamentId={T}"),json!({"balance":serde_json::from_str::<Value>(&moloch_replay::money(cash)).unwrap(),"availableAdvance":0,"buyingPower":serde_json::from_str::<Value>(&moloch_replay::money(cash)).unwrap()})),positions:r(format!("/tournaments/{}/portfolio/positions",scope.tournament_slug),json!({"positions":positions})),open_orders:r(format!("/orders?status=open&limit=200&tournamentId={T}"),json!({"data":[],"pagination":{"hasMore":false},"coverage":{"complete":true}})),components};Self{f,b,plan,basket,permit,spec,facts,at}
 }
 fn ready(&self)->feedback::Result<Prepared>{Prepared::new_portfolio(&self.b.bank,&self.b.activation,&self.f.census.cache.scope,&self.plan,&self.basket,self.permit.clone(),self.facts.clone(),self.at,self.b.activation.entry_until_ms)}
 fn authority(&self)->authority::ProductionAuthority{use moloch_replay::session::ExclusiveLock;let binary=self.b.path.join("physical-test-binary");let control=self.b.path.join("physical-control");std::fs::write(&binary,b"checked signed portfolio fixture").unwrap();std::fs::write(&control,b"unchanged").unwrap();let mut a=self.b.activation.clone();a.binary_sha256=format!("{:x}",Sha256::digest(std::fs::read(&binary).unwrap()));let auth=authority::ProductionAuthority::new(a,self.f.census.cache.scope.clone(),vec![self.b.path.join("STOP")],control,binary,std::sync::Arc::new(ExclusiveLock::acquire(&self.b.path.join("physical.lock")).unwrap())).unwrap();auth.bind_stream(std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),self.at+60000);auth}
}
#[test]fn one_leg_held_complement_buy_requires_real_native_attempt_and_preserves_inventory(){let a=A::buy();assert_eq!(a.plan.legs().len(),1);assert_eq!(a.plan.legs()[0].exchange_id,"102");assert_eq!(a.b.bank.engine().wallet.quantity("101",moloch_replay::Side::No),5);let p=a.ready().unwrap();assert!(p.requires_entry());p.authorize(&a.spec,&a.permit,a.at,&BTreeSet::new(),a.b.activation.entry_until_ms).unwrap();assert!(a.b.bank.engine().fills().is_empty());assert_eq!(a.b.bank.engine().wallet.quantity("102",moloch_replay::Side::No),0);let auth=a.authority();let log=moloch_live_runtime::dispatch::DispatchLog::open(&a.b.path.join("ordinary.ndjson")).unwrap();auth.prepare_portfolio(&a.b.bank,&a.plan,a.permit.clone(),a.facts.clone(),&log,a.at).unwrap();auth.authorize(&a.f.census.cache.scope,&a.spec,&a.permit,true,a.at).unwrap();}
#[test]fn whole_covered_sell_remains_authorized_after_entry_deadline_without_relabeling_cash(){let a=A::sell();assert!(a.at>a.b.activation.entry_until_ms);assert!(a.basket.legs.iter().all(|l|l.action==wire::Action::Sell));assert_eq!(a.basket.maximum_gross_buy_cost,"0.000000");let before=a.b.bank.engine().report().unwrap();let p=a.ready().unwrap();assert!(!p.requires_entry());p.authorize(&a.spec,&a.permit,a.at,&BTreeSet::new(),a.b.activation.entry_until_ms).unwrap();assert_eq!(a.b.bank.engine().report().unwrap(),before);let auth=a.authority();let log=moloch_live_runtime::dispatch::DispatchLog::open(&a.b.path.join("ordinary.ndjson")).unwrap();auth.prepare_portfolio(&a.b.bank,&a.plan,a.permit.clone(),a.facts.clone(),&log,a.at).unwrap();auth.authorize(&a.f.census.cache.scope,&a.spec,&a.permit,true,a.at).unwrap();}
#[test]fn physical_positions_must_match_entire_held_component_not_only_new_wire_leg(){for mode in ["missing","quantity","side","duplicate"]{let mut a=A::buy();match mode{"missing"=>a.facts.positions.data["positions"]=json!([]),"quantity"=>a.facts.positions.data["positions"][0]["quantity"]=json!(-4),"side"=>a.facts.positions.data["positions"][0]["quantity"]=json!(5),_=>{let row=a.facts.positions.data["positions"][0].clone();a.facts.positions.data["positions"].as_array_mut().unwrap().push(row);}}assert!(a.ready().is_err(),"{mode}");}}
#[test]fn changed_reviewed_rule_gross_funding_or_cash_credit_cannot_authorize(){for mode in ["rule","gross","cash","wire_side"]{let mut a=A::buy();match mode{"rule"=>a.facts.components.get_mut("102").unwrap().contract.data["newRefundCondition"]=json!("changed"),"gross"=>a.basket.maximum_gross_buy_cost="0.000000".into(),"cash"=>a.facts.cash_balance.data=json!({"balance":1,"availableAdvance":999,"buyingPower":1000}),_=>a.basket.legs[0].side=multi_leg::Side::Yes}assert!(a.ready().is_err(),"{mode}");}}
#[test]fn original_side_fixed_limit_full_depth_required_for_both_buy_and_sell(){for sell in [false,true]{for mode in ["depth","wrong_side","crossed"]{let mut a=if sell{A::sell()}else{A::buy()};let ex=a.basket.legs[0].exchange_id.clone();let b=&mut a.facts.components.get_mut(&ex).unwrap().book.data["contexts"][0]["orderbook"]["exchanges"][0];match mode{"depth"=>{let key=if sell{"asks"}else{"bids"};b[key][0]["quantity"]=json!(4);},"wrong_side"=>{if sell{b["asks"][0]["price"]=json!(0.8)}else{b["bids"][0]["price"]=json!(0.1)}},_=>b["bids"][0]["price"]=json!(0.9)}assert!(a.ready().is_err(),"sell={sell} {mode}");}}}
#[test]fn unknown_prior_physical_attempt_blocks_even_with_complete_fresh_empty_open_list(){let a=A::buy();let auth=a.authority();let path=a.b.path.join("ordinary.ndjson");{let mut log=moloch_live_runtime::dispatch::DispatchLog::open(&path).unwrap();log.append(json!({"kind":"intent","qid":999})).unwrap();log.append(json!({"kind":"attempt","qid":999})).unwrap();}let log=moloch_live_runtime::dispatch::DispatchLog::open(&path).unwrap();assert!(a.ready().is_ok());assert!(auth.prepare_portfolio(&a.b.bank,&a.plan,a.permit.clone(),a.facts.clone(),&log,a.at).is_err());assert!(auth.authorize(&a.f.census.cache.scope,&a.spec,&a.permit,true,a.at).is_err());}
#[test]fn physical_binding_does_not_reuse_permit_payload_or_extend_original_plan(){let a=A::buy();let p=a.ready().unwrap();for mode in ["body","bytes","permit","expired"]{let mut s=a.spec.clone();let mut permit=a.permit.clone();let mut at=a.at;match mode{"body"=>s.body.as_mut().unwrap()["legs"][0]["action"]=json!("sell"),"bytes"=>s.body_json=Some("{}".into()),"permit"=>permit.maximum_cost="100.000000".into(),_=>at=a.plan.expires_at_ms()}assert!(p.authorize(&s,&permit,at,&BTreeSet::new(),a.b.activation.entry_until_ms).is_err(),"{mode}");}}
#[test]fn held_component_outside_one_leg_wire_still_requires_fresh_complete_reviewed_facts(){for mode in ["missing","rule","market","book"]{let mut a=A::buy();assert!(a.basket.legs.iter().all(|l|l.exchange_id!="101"));match mode{"missing"=>{a.facts.components.remove("101");},"rule"=>a.facts.components.get_mut("101").unwrap().contract.data["refundRule"]=json!("changed"),"market"=>a.facts.components.get_mut("101").unwrap().market.data["status"]=json!("closed"),_=>a.facts.components.get_mut("101").unwrap().book.data["contexts"][0]["orderbook"]["exchanges"][0]["asOf"]["at"]=json!(stamp(a.at-10001))}assert!(a.ready().is_err(),"{mode}");}}
